export enum SupportedDatastores {
    s3 = 's3',
}

/**
 * The default datastore platform used when a `platform` is not supplied.
 */
export const DEFAULT_DATASTORE_PLATFORM = SupportedDatastores.s3;

/**
 * The default region used when a `region` is not supplied.
 */
export const DEFAULT_DATASTORE_REGION = 'us-east-1';

/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions.
 * Specifically this is the access information needed for the connectors which pull usage data out of a datastore
 * owned/written to by a Paigo customer. Today the only supported datastore platform is `s3`.
 *
 * A SaaS business only ever provides the AWS `accountId` which is allowed to deliver usage records.
 * Everything else (`iamRoleArn`, `externalId`, `ingestion`, `dlq`) is generated by Paigo while provisioning
 * the access and is returned/persisted alongside the configuration.
 * */
export class DatastoreAccessInformation {
    private static readonly logger = new Logger(DatastoreAccessInformation.name);

    /**
     * The underlying datastore platform which paigo ingests usage records from. Optional, default is `s3`.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        example: 's3',
    })
    public platform?: SupportedDatastores;

    /**
     * The unique ID of the cloud account which owns the usage records and which is trusted to deliver them.
     * Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     * The region the ingestion datastore lives in. Optional, default is `us-east-1`.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: DEFAULT_DATASTORE_REGION })
    public region?: string;

    /**
     * READ ONLY. The IAM role generated by Paigo which the `accountId` assumes in order to deliver usage records.
     * <br><br>
     * Example `"arn:aws:iam::647662420899:role/paigo-dev-s3-ingestion-fakeBusiness-1a2b3c4d"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, readOnly: true })
    public iamRoleArn?: string;

    /**
     * READ ONLY. The external ID which must be presented while assuming the generated `iamRoleArn`.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, readOnly: true })
    public externalId?: string;

    /**
     * READ ONLY. The location usage records are delivered to.
     * <br><br>
     * Example `"s3://paigo-usage-record-dump-bucket/fakeBusiness/"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, readOnly: true })
    public ingestion?: string;

    /**
     * READ ONLY. The location records which failed processing are delivered to.
     * <br><br>
     * Example `"s3://paigo-usage-record-dlq-bucket/fakeBusiness/"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, readOnly: true })
    public dlq?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID?: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation & { [x: string]: any }) {
        if (datastoreAccessInformation) {
            const { platform, accountId, region, iamRoleArn, externalId, ingestion, dlq, businessID } =
                datastoreAccessInformation;
            // `datastoreType`/`cloudId` are the legacy names of `platform`/`accountId`.
            const legacyPlatform = datastoreAccessInformation['datastoreType'];
            const legacyAccountId = datastoreAccessInformation['cloudId'];

            this.platform = (platform ? platform : legacyPlatform ? legacyPlatform : DEFAULT_DATASTORE_PLATFORM)
                .toString()
                .toLowerCase() as SupportedDatastores;
            this.accountId = accountId !== undefined && accountId !== null ? `${accountId}` : legacyAccountId;
            this.region = region ? region : DEFAULT_DATASTORE_REGION;
            if (iamRoleArn) {
                this.iamRoleArn = iamRoleArn;
            }
            if (externalId) {
                this.externalId = externalId;
            }
            this.businessID = businessID;
            this.ingestion = ingestion ? ingestion : DatastoreAccessInformation.ingestionLocation(businessID);
            this.dlq = dlq ? dlq : DatastoreAccessInformation.dlqLocation(businessID);
        }
    }

    /**
     * The bucket usage records are delivered to by a SaaS business.
     */
    public static get ingestionBucket(): string {
        return process.env.DB_MEASUREMENT_BUCKET_NAME
            ? process.env.DB_MEASUREMENT_BUCKET_NAME
            : 'paigo-usage-record-dump-bucket';
    }

    /**
     * The bucket usage records which failed processing are delivered to.
     */
    public static get dlqBucket(): string {
        return process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME
            ? process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME
            : 'paigo-usage-record-dlq-bucket';
    }

    /**
     * Every SaaS business gets its own prefix inside of the shared ingestion/dlq buckets.
     */
    public static prefixForBusiness(businessID: string): string {
        return `${businessID}/`;
    }

    public static ingestionLocation(businessID: string): string {
        return `s3://${DatastoreAccessInformation.ingestionBucket}/${DatastoreAccessInformation.prefixForBusiness(
            businessID
        )}`;
    }

    public static dlqLocation(businessID: string): string {
        return `s3://${DatastoreAccessInformation.dlqBucket}/${DatastoreAccessInformation.prefixForBusiness(
            businessID
        )}`;
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, region, iamRoleArn, externalId, ingestion, dlq } =
                datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (region) influxPoint.tag('region', region);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        region,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        businessID,
        datastoreType,
        cloudId,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform: platform ? platform : datastoreType,
            accountId: accountId ? accountId : cloudId,
            region,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            businessID,
        } as DatastoreAccessInformation);
    }

    /**
     * IAM only accepts alphanumeric characters and `+=,.@-_` inside of role and policy names.
     */
    private static sanitizeForIAM(value: string): string {
        return `${value ? value : 'unknown'}`.replace(/[^\w+=,.@-]/g, '-');
    }

    /**
     * Builds a unique name for the IAM resources provisioned for a SaaS business.
     * IAM role names are limited to 64 characters.
     */
    public static buildResourceName(businessID: string, uniqueSuffix: string): string {
        const stage = process.env.STAGE ? process.env.STAGE : 'dev';
        const base = DatastoreAccessInformation.sanitizeForIAM(
            `paigo-${stage}-s3-ingestion-${DatastoreAccessInformation.sanitizeForIAM(businessID)}`
        );
        const maxBaseLength = 64 - uniqueSuffix.length - 1;
        return `${base.slice(0, maxBaseLength)}-${uniqueSuffix}`;
    }

    /**
     * The trust relationship allowing the SaaS business account to assume the Paigo owned ingestion role.
     */
    public static buildTrustPolicy({ accountId, externalId }: { accountId: string; externalId: string }) {
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'PaigoUsageIngestionTrust',
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };
    }

    /**
     * The permissions granted to the generated role. Scoped down to the prefixes owned by this business only.
     */
    public static buildAccessPolicy(businessID: string) {
        const prefix = DatastoreAccessInformation.prefixForBusiness(businessID);
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'PaigoUsageIngestion',
                    Effect: 'Allow',
                    Action: ['s3:PutObject', 's3:GetObject', 's3:AbortMultipartUpload'],
                    Resource: [`arn:aws:s3:::${DatastoreAccessInformation.ingestionBucket}/${prefix}*`],
                },
                {
                    Sid: 'PaigoUsageDeadLetterQueue',
                    Effect: 'Allow',
                    Action: ['s3:GetObject'],
                    Resource: [`arn:aws:s3:::${DatastoreAccessInformation.dlqBucket}/${prefix}*`],
                },
                {
                    Sid: 'PaigoUsageListBuckets',
                    Effect: 'Allow',
                    Action: ['s3:ListBucket'],
                    Resource: [
                        `arn:aws:s3:::${DatastoreAccessInformation.ingestionBucket}`,
                        `arn:aws:s3:::${DatastoreAccessInformation.dlqBucket}`,
                    ],
                    Condition: {
                        StringLike: {
                            's3:prefix': [`${prefix}*`],
                        },
                    },
                },
            ],
        };
    }

    /**
     * Provisions the access required for a SaaS business to deliver usage records into Paigo.
     * A dedicated, uniquely named IAM role + policy is created per measurement and the SaaS business
     * account is trusted to assume it with a freshly generated external ID.
     *
     * @returns the configuration enriched with the generated access information.
     */
    public static async setupAccess(
        dbAccessInformation: DatastoreAccessInformation
    ): Promise<DatastoreAccessInformation> {
        const { accountId, businessID, platform, region } = dbAccessInformation;
        if (platform && platform.toLowerCase() !== SupportedDatastores.s3) {
            throw new BadRequestException(`Unsupported datastore platform: ${platform}`);
        }
        if (!accountId) {
            throw new BadRequestException('accountId is required for datastore based measurements');
        }
        const externalId = randomUUID();
        const roleName = DatastoreAccessInformation.buildResourceName(businessID, randomUUID().slice(0, 8));
        const policyName = `${roleName}-policy`;
        const client = DatastoreAccessInformation.iamClient(region);
        try {
            const { Role } = await client.send(
                new CreateRoleCommand({
                    RoleName: roleName,
                    Description: `Paigo usage record ingestion role for ${businessID}`,
                    AssumeRolePolicyDocument: JSON.stringify(
                        DatastoreAccessInformation.buildTrustPolicy({ accountId, externalId })
                    ),
                })
            );
            const { Policy } = await client.send(
                new CreatePolicyCommand({
                    PolicyName: policyName,
                    Description: `Paigo usage record ingestion policy for ${businessID}`,
                    PolicyDocument: JSON.stringify(DatastoreAccessInformation.buildAccessPolicy(businessID)),
                })
            );
            await client.send(
                new AttachRolePolicyCommand({
                    RoleName: roleName,
                    PolicyArn: Policy?.Arn ? Policy.Arn : DatastoreAccessInformation.fallbackPolicyArn(policyName),
                })
            );
            const iamRoleArn = Role?.Arn ? Role.Arn : DatastoreAccessInformation.fallbackRoleArn(roleName);
            DatastoreAccessInformation.logger.log(
                `Provisioned datastore based access for ${businessID} using role ${iamRoleArn}`
            );

            return new DatastoreAccessInformation({
                ...dbAccessInformation,
                iamRoleArn,
                externalId,
            } as DatastoreAccessInformation);
        } catch (e) {
            throw DatastoreAccessInformation.toHttpException(e, accountId);
        }
    }

    /**
     * Updates the trust relationship of an already provisioned role so a new `accountId` can deliver usage records.
     * The generated role and external ID are always preserved.
     *
     * @returns the configuration with the preserved access information.
     */
    public static async updateAccess(
        dbAccessInformation: DatastoreAccessInformation,
        previousAccessInformation: DatastoreAccessInformation
    ): Promise<DatastoreAccessInformation> {
        const iamRoleArn = previousAccessInformation?.iamRoleArn
            ? previousAccessInformation.iamRoleArn
            : dbAccessInformation?.iamRoleArn;
        const externalId = previousAccessInformation?.externalId
            ? previousAccessInformation.externalId
            : dbAccessInformation?.externalId;
        const accountId = dbAccessInformation?.accountId
            ? dbAccessInformation.accountId
            : previousAccessInformation?.accountId;

        const preserved = new DatastoreAccessInformation({
            ...dbAccessInformation,
            accountId,
            iamRoleArn,
            externalId,
        } as DatastoreAccessInformation);

        if (!iamRoleArn || !externalId) {
            // Nothing was ever provisioned for this measurement, provision it now.
            return DatastoreAccessInformation.setupAccess(preserved);
        }
        if (previousAccessInformation?.accountId === accountId) {
            return preserved;
        }
        const roleName = DatastoreAccessInformation.roleNameFromArn(iamRoleArn);
        try {
            await DatastoreAccessInformation.iamClient(preserved.region).send(
                new UpdateAssumeRolePolicyCommand({
                    RoleName: roleName,
                    PolicyDocument: JSON.stringify(
                        DatastoreAccessInformation.buildTrustPolicy({ accountId, externalId })
                    ),
                })
            );
        } catch (e) {
            throw DatastoreAccessInformation.toHttpException(e, accountId);
        }
        DatastoreAccessInformation.logger.log(`Updated the trust policy of ${roleName} to trust ${accountId}`);

        return preserved;
    }

    public static roleNameFromArn(iamRoleArn: string): string {
        return `${iamRoleArn}`.split('/').pop();
    }

    private static iamClient(region?: string): IAMClient {
        return new IAMClient({ region: region ? region : DEFAULT_DATASTORE_REGION });
    }

    private static get paigoAccountId(): string {
        return process.env.PAIGO_AWS_ACCOUNT_ID ? process.env.PAIGO_AWS_ACCOUNT_ID : '647662420899';
    }

    private static fallbackRoleArn(roleName: string): string {
        return `arn:aws:iam::${DatastoreAccessInformation.paigoAccountId}:role/${roleName}`;
    }

    private static fallbackPolicyArn(policyName: string): string {
        return `arn:aws:iam::${DatastoreAccessInformation.paigoAccountId}:policy/${policyName}`;
    }

    private static toHttpException(e, accountId: string) {
        const code = e?.Code ? e.Code : e?.name;
        if (code === 'MalformedPolicyDocument' || code === 'MalformedPolicy' || code === 'InvalidInput') {
            return new BadRequestException(`AccountId: ${accountId} is invalid`);
        }
        DatastoreAccessInformation.logger.error('Failed to provision datastore based access', e);
        return e;
    }
}

