import { ApiHideProperty } from '@nestjs/swagger';
import { IsOptional, IsString } from 'class-validator';
import { putDocument } from '../../utils/aws/s3';
import { CreateUsageDto } from './create-usage.dto';

/**
 * The suffix appended to the mirrored source key when a record is written to the dead letter queue.
 */
export const DLQ_KEY_SUFFIX = '.message.text';

/**
 * The payload delivered by the internal datastore (s3) connector.
 * `message` is a single, standard usage record and `s3Key` is the key of the object the record was read from.
 * The first segment of `s3Key` is always the businessID the record belongs to.
 */
export class DbMeasuredusageDto {
    /**
     * A single standard usage record, as delivered by the connector.
     */
    @ApiHideProperty()
    @IsOptional()
    public message: string | CreateUsageDto;

    /**
     * The source key of the object the usage record was read from.
     * The first segment is the businessID.
     * @example 'fakeBusiness/2023/02/08/usage-record.json'
     */
    @ApiHideProperty()
    @IsString()
    @IsOptional()
    public s3Key: string;

    /**
     * Normalises a source key into a key which is relative to the bucket it lives in.
     * Fully qualified locations (`s3://bucket/key`, `arn:aws:s3:::bucket/key`) are reduced to `key`,
     * keys which are already relative are returned untouched (minus any leading slashes).
     */
    public static relativeSourceKey(s3Key: string): string {
        if (!s3Key) {
            return '';
        }
        let key = `${s3Key}`.trim();
        if (/^s3[an]?:\/\//i.test(key)) {
            // s3://bucket/some/key -> some/key
            key = key.replace(/^s3[an]?:\/\//i, '').split('/').slice(1).join('/');
        } else if (/^arn:aws:s3:::/i.test(key)) {
            // arn:aws:s3:::bucket/some/key -> some/key
            key = key.replace(/^arn:aws:s3:::/i, '').split('/').slice(1).join('/');
        }
        // Already relative keys just get their leading slashes removed
        return key.replace(/^\/+/, '');
    }

    /**
     * The businessID a record belongs to is the first segment of its source key.
     */
    public static businessIDFromSourceKey(s3Key: string): string {
        const [businessID] = DbMeasuredusageDto.relativeSourceKey(s3Key).split('/');
        return businessID;
    }

    /**
     * The dead letter queue mirrors the source key of the record which failed to process.
     */
    public static deadLetterQueueKey(s3Key: string): string {
        return `${DbMeasuredusageDto.relativeSourceKey(s3Key)}${DLQ_KEY_SUFFIX}`;
    }

    /**
     * The bucket failed records are written to.
     */
    public static get deadLetterQueueBucket(): string {
        return process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME
            ? process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME
            : 'paigo-usage-record-dlq-bucket';
    }

    /**
     * Writes a record which could not be processed to the dead letter queue,
     * alongside the metadata required to reprocess it manually.
     */
    public static async writeToDeadLetterQueue({
        input,
        error,
        s3Key,
    }: {
        input: DbMeasuredusageDto | { [x: string]: any };
        error?: any;
        s3Key: string;
    }) {
        const sourceKey = DbMeasuredusageDto.relativeSourceKey(s3Key);
        const key = DbMeasuredusageDto.deadLetterQueueKey(s3Key);
        const document = {
            input,
            businessID: DbMeasuredusageDto.businessIDFromSourceKey(s3Key),
            sourceKey,
            dlqKey: key,
            error: error?.message ? error.message : error ? `${error}` : 'Failed to process usage record',
            failedAt: new Date().toISOString(),
        };
        await putDocument(JSON.stringify(document), DbMeasuredusageDto.deadLetterQueueBucket, key).done();

        return { bucket: DbMeasuredusageDto.deadLetterQueueBucket, key, document };
    }
}

arguments.newString:
    /**
     * Collect usage data delivered by the internal datastore (s3) connector.
     * The connector posts a single, standard usage record together with the key of the object it was read from.
     * The first segment of that key is the businessID the record belongs to.
     *
     * Records which cannot be processed are written to the dead letter queue instead of being rejected,
     * so the connector never has to retry a poisonous record.
     */
    @UseGuards(LogGaurd, AuthGuard('jwt'))
    @Post('db')
    async dbUsage(@Body() createUsageDto) {
        UsageController.logger.log('Starting DB Usage Endpoint execution');

        const { message, s3Key } = createUsageDto ? createUsageDto : ({} as DbMeasuredusageDto);
        if (!s3Key) {
            throw new BadRequestException('An s3Key is required to attribute a datastore based usage record');
        }
        // TODO: check if the passed in BusinessID is an authorized producer, if not throw message away
        const businessID = DbMeasuredusageDto.businessIDFromSourceKey(s3Key);
        try {
            if (!businessID) {
                throw new Error(`Unable to determine the businessID from the source key: ${s3Key}`);
            }
            const parsed = typeof message === 'string' ? JSON.parse(message) : message;
            if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
                throw new Error('The usage record must be a single standard usage record');
            }
            return await this.usageService.create({ ...parsed, businessID });
        } catch (e) {
            UsageController.logger.error(
                `Failed to process the usage record found at ${s3Key}, writing it to the dead letter queue`,
                e
            );
            const { key } = await DbMeasuredusageDto.writeToDeadLetterQueue({
                input: createUsageDto,
                error: e,
                s3Key,
            });

            return { message: `Failed to process usage record, wrote it to the dead letter queue as ${key}` };
        }
    }
}

arguments.oldString:
    @UseGuards(LogGaurd, AuthGuard('jwt'))
    @Post('db')
    dbUsage(@Body() createUsageDto) {
        // Custom validator for DB usage, on failure push to DLQ for manual processing

        UsageController.logger.log('Starting DB Usage Endpoint execution');

        const { message, s3Key } = createUsageDto;
        // TODO: check if the passed in BusinessID is an authorized producer, if not throw message away
        if (s3Key) {
            const [businessID] = s3Key.split('/');
            const parsed = JSON.parse(message);
            const input = { ...parsed, businessID };
            return this.usageService.create(input);
        } else {
            // TODO push to DLQ
            return '';
        }
    }
}

