describe('UsageController datastore based (s3 connector) usage', () => {
    const s3Mock = mockClient(S3Client);
    let controller: UsageController;
    const mockCreate = jest.fn().mockResolvedValue({ message: 'Measurement created' });

    beforeEach(async () => {
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'fake-dlq-bucket';
        s3Mock.reset();
        s3Mock.on(PutObjectCommand).resolves({});
        const module: TestingModule = await Test.createTestingModule({
            controllers: [UsageController],
        })
            .useMocker((token) => {
                if (token === UsageService) {
                    return { create: mockCreate };
                }
            })
            .compile();

        controller = module.get<UsageController>(UsageController);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    const validRecord = {
        timeStamp: '2023-02-08T19:24:10Z',
        applicationId: 'fakeApplication',
        dimensionId: 'fakeDimension',
        recordValue: '0.87',
    };

    it('sends a valid record through the usage service using the businessID from the first key segment', async () => {
        await controller.dbUsage({
            message: JSON.stringify(validRecord),
            s3Key: 'fakeBusiness/2023/02/08/usage-record.json',
        });

        expect(mockCreate).toHaveBeenCalledWith({ ...validRecord, businessID: 'fakeBusiness' });
        expect(s3Mock.commandCalls(PutObjectCommand).length).toBe(0);
    });

    it('resolves the businessID out of a fully qualified source key', async () => {
        await controller.dbUsage({
            message: JSON.stringify(validRecord),
            s3Key: 's3://paigo-usage-record-dump-bucket/fakeBusiness/2023/02/08/usage-record.json',
        });

        expect(mockCreate).toHaveBeenCalledWith({ ...validRecord, businessID: 'fakeBusiness' });
    });

    it('writes malformed records to the dlq mirroring the relative source key', async () => {
        const input = { message: '{not-json', s3Key: 'fakeBusiness/2023/02/08/usage-record.json' };
        await controller.dbUsage(input);

        expect(mockCreate).not.toHaveBeenCalled();
        const [call] = s3Mock.commandCalls(PutObjectCommand);
        expect(call.args[0].input.Bucket).toBe('fake-dlq-bucket');
        expect(call.args[0].input.Key).toBe('fakeBusiness/2023/02/08/usage-record.json.message.text');
        const document = JSON.parse(call.args[0].input.Body as string);
        expect(document.input).toEqual(input);
        expect(document.businessID).toBe('fakeBusiness');
        expect(document.sourceKey).toBe('fakeBusiness/2023/02/08/usage-record.json');
        expect(document.error).toBeDefined();
        expect(document.failedAt).toBeDefined();
    });

    it('mirrors fully qualified source keys into the dlq as relative keys', async () => {
        await controller.dbUsage({
            message: 'not-json-at-all',
            s3Key: 's3://paigo-usage-record-dump-bucket/fakeBusiness/broken.json',
        });

        const [call] = s3Mock.commandCalls(PutObjectCommand);
        expect(call.args[0].input.Key).toBe('fakeBusiness/broken.json.message.text');
    });

    it('writes records the usage service could not process to the dlq', async () => {
        mockCreate.mockRejectedValueOnce(new Error('no such dimension'));
        await controller.dbUsage({
            message: JSON.stringify(validRecord),
            s3Key: 'fakeBusiness/usage-record.json',
        });

        const [call] = s3Mock.commandCalls(PutObjectCommand);
        expect(call.args[0].input.Key).toBe('fakeBusiness/usage-record.json.message.text');
        expect(JSON.parse(call.args[0].input.Body as string).error).toBe('no such dimension');
    });

    it('rejects payloads without a source key', async () => {
        await expect(controller.dbUsage({ message: JSON.stringify(validRecord) })).rejects.toThrow(
            BadRequestException
        );
    });
});
