    const mockLoadPoints = jest.fn();
    const tags: Record<string, string> = {};
    const mockReadMeasurementConfigData = jest.fn();

    beforeEach(async () => {
        process.env.STAGE = 'test';
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'fake-ingestion-bucket';
