        Object.keys(tags).forEach((key) => delete tags[key]);
        iamMock.reset();
        iamMock.on(CreateRoleCommand).callsFake(({ RoleName }) => ({
            Role: { Arn: `arn:aws:iam::647662420899:role/${RoleName}` },
        }));
        iamMock.on(CreatePolicyCommand).callsFake(({ PolicyName }) => ({
            Policy: { Arn: `arn:aws:iam::647662420899:policy/${PolicyName}` },
        }));
        iamMock.on(AttachRolePolicyCommand).resolves({});
        iamMock.on(UpdateAssumeRolePolicyCommand).resolves({});

        const module: TestingModule = await Test.createTestingModule({
            providers: [MeasurementConfigService],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return {
                        loadPoints: mockLoadPoints,
                        getPoint: () => ({
                            tag: (key: string, value: string) => {
                                tags[key] = value;
                            },
                            stringField: jest.fn(),
                        }),
                        readMeasurementConfigData: mockReadMeasurementConfigData,
                    };
                }
                if (token === SchedulerService) {
                    return { create: jest.fn() };
                }
                if (token === DimensionsService) {
