        service = module.get<MeasurementConfigService>(MeasurementConfigService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    const createInput = {
        measurementMode: measurementMode.datastoreBased,
        measurementConfiguration: { platform: SupportedDatastores.s3, accountId: '623673123435' },
        businessID: 'fakeBusiness',
        measurementName: 'datastore measurement',
    };

    it('provisions a uniquely named role and policy scoped to the business prefixes', async () => {
        const response = await service.create(createInput as any, 'fakeSubject');
        const configuration = response.measurementConfiguration as DatastoreAccessInformation;

        expect(configuration.platform).toBe('s3');
        expect(configuration.accountId).toBe('623673123435');
        expect(configuration.region).toBe('us-east-1');
        expect(configuration.ingestion).toBe('s3://fake-ingestion-bucket/fakeBusiness/');
        expect(configuration.dlq).toBe('s3://fake-dlq-bucket/fakeBusiness/');
        expect(configuration.externalId).toBeDefined();

        const [createRole] = iamMock.commandCalls(CreateRoleCommand);
        const roleName = createRole.args[0].input.RoleName;
        expect(roleName).toContain('paigo-test-s3-ingestion-fakeBusiness');
        expect(roleName.length).toBeLessThanOrEqual(64);
        expect(configuration.iamRoleArn).toBe(`arn:aws:iam::647662420899:role/${roleName}`);

        const trust = JSON.parse(createRole.args[0].input.AssumeRolePolicyDocument);
        expect(trust.Statement[0].Principal.AWS).toBe('arn:aws:iam::623673123435:root');
        expect(trust.Statement[0].Condition.StringEquals['sts:ExternalId']).toBe(configuration.externalId);

        const [createPolicy] = iamMock.commandCalls(CreatePolicyCommand);
        expect(createPolicy.args[0].input.PolicyName).toBe(`${roleName}-policy`);
        const policy = JSON.parse(createPolicy.args[0].input.PolicyDocument);
        expect(policy.Statement[0].Resource).toEqual(['arn:aws:s3:::fake-ingestion-bucket/fakeBusiness/*']);
        expect(policy.Statement[1].Resource).toEqual(['arn:aws:s3:::fake-dlq-bucket/fakeBusiness/*']);

