export enum SupportedDatastores {
    s3 = 's3',
}

/**
 * The default datastore platform used when a `platform` is not supplied.
 */
export const DEFAULT_DATASTORE_PLATFORM = SupportedDatastores.s3;

/**
 * The default region used when a `region` is not supplied.
 */
export const DEFAULT_DATASTORE_REGION = 'us-east-1';

/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions.
 * Specifically this is the access information needed for the connectors which pull usage data out of a datastore
 * owned/written to by a Paigo customer. Today the only supported datastore platform is `s3`.
 *
 * A SaaS business only ever provides the AWS `accountId` which is allowed to deliver usage records.
 * Everything else (`iamRoleArn`, `externalId`, `ingestion`, `dlq`) is generated by Paigo while provisioning
 * the access and is returned/persisted alongside the configuration.
 * */
export class DatastoreAccessInformation {
    private static readonly logger = new Logger(DatastoreAccessInformation.name);

    /**
     * The underlying datastore platform which paigo ingests usage records from. Optional, default is `s3`.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        example: 's3',
    })
    public platform?: SupportedDatastores;

    /**
     * The unique ID of the cloud account which owns the usage records and which is trusted to deliver them.
     * Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     * The region the ingestion datastore lives in. Optional, default is `us-east-1`.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: DEFAULT_DATASTORE_REGION })
    public region?: string;

    /**
     * READ ONLY. The IAM role generated by Paigo which the `accountId` assumes in order to deliver usage records.
     * <br><br>
     * Example `"arn:aws:iam::647662420899:role/paigo-dev-s3-ingestion-fakeBusiness-1a2b3c4d"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, readOnly: true })
    public iamRoleArn?: string;

